def find_zero(xs: list):
    if len(xs) % 2 != 0:
        raise ValueError('The number of coefficients must be even.')

    # Ensure the largest non-zero coefficient is positive
    max_coeff = max(abs(coeff) for coeff in xs)
    if max_coeff == 0:
        raise ValueError('All coefficients are zero, no solution exists.')

    a, b = -max_coeff, max_coeff
    while abs(b - a) > 1e-6:
        mid = (a + b) / 2
        if poly(xs, a) * poly(xs, mid) <= 0:
            b = mid
        else:
            a = mid

    return a

